// Initialize router
const maxConcurrent = 5;

console.log('=== ROUTER CYCLE START ===');
console.log(`Max concurrent: ${maxConcurrent}`);

return [{ json: { maxConcurrent } }];

// Calculate available slots
const response = $input.first().json;
const currentProcessing = response.processing_count || 0;
const maxConcurrent = $('Initialize Router').first().json.maxConcurrent;
const availableSlots = Math.max(0, maxConcurrent - currentProcessing);
const queuedCount = response.queued_count || 0;

console.log(`Currently processing: ${currentProcessing}/${maxConcurrent}`);
console.log(`Available slots: ${availableSlots}`);
console.log(`Queued orders: ${queuedCount}`);

if (availableSlots === 0) {
  console.log('⏸️ At capacity - will check false path');
}

return [{
  json: {
    availableSlots: availableSlots,
    currentProcessing: currentProcessing,
    queuedCount: queuedCount,
    shouldFetchOrders: availableSlots > 0
  }
}];

// FALSE PATH - At Capacity
const data = $input.first().json;
const queuedCount = data.queuedCount || 0;

console.log('=== AT CAPACITY ===');
console.log(`Queued: ${queuedCount} orders waiting`);
console.log('Next check in 30 seconds');

// Use workflow static data to persist counters across executions
const s = this.getWorkflowStaticData('global');
const capacityFullCycles = (s.capacityFullCycles || 0) + 1;
s.capacityFullCycles = capacityFullCycles;
s.lastCapacityCheckAt = new Date().toISOString();
console.log(`Capacity full for ${capacityFullCycles} consecutive cycles`);

// Trigger stuck check after 5 cycles
if (capacityFullCycles >= 5) {
  return [{
    json: {
      shouldCheckStuck: true,
      capacityFullCycles,
      queuedCount
    }
  }];
}

// Normal case - just log and exit
return [];

// Check for stuck workflows
const supabaseUrl = 'https://mdnthwpcnphjnnblbvxk.supabase.co';
const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1kbnRod3BjbnBoam5uYmxidnhrIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MDUwMDc4MCwiZXhwIjoyMDc2MDc2NzgwfQ.wNVQ3U2nWTGu8VsuXKasWOCxVhpca5x42wSapQDinGs';

if (!supabaseUrl || !supabaseKey) {
  console.warn('⚠️ Supabase not configured - skipping stuck workflow check');
  return [];
}

// Query for workflows running > 30 minutes
const thirtyMinutesAgo = new Date(Date.now() - 30 * 60 * 1000).toISOString();

try {
  const response = await fetch(
    `${supabaseUrl}/rest/v1/orders?execution_status=eq.processing&started_at=lt.${thirtyMinutesAgo}&select=amazon_order_id,current_workflow,started_at`,
    {
      headers: {
        'apikey': supabaseKey,
        'Authorization': `Bearer ${supabaseKey}`
      }
    }
  );

  const stuckOrders = await response.json();

  if (!Array.isArray(stuckOrders) || stuckOrders.length === 0) {
    console.log('✅ No stuck workflows detected');

    // Reset capacity counter since everything is processing normally
    this.getWorkflowStaticData('global').capacityFullCycles = 0;

    return [];
  }

  // Found stuck workflows!
  console.error(`🚨 ALERT: ${stuckOrders.length} stuck workflows detected!`);

  const alerts = stuckOrders.map(order => {
    const startedAt = new Date(order.started_at);
    const runningMinutes = Math.floor((Date.now() - startedAt.getTime()) / 1000 / 60);

    console.error(`  - Order ${order.amazon_order_id}: ${order.current_workflow} running for ${runningMinutes} minutes`);

    return {
      orderId: order.amazon_order_id,
      workflow: order.current_workflow,
      runningMinutes: runningMinutes,
      startedAt: order.started_at
    };
  });

  // Return alerts for notification
  return [{
    json: {
      alert: true,
      level: 'critical',
      type: 'stuck_workflows',
      count: stuckOrders.length,
      workflows: alerts,
      message: `${stuckOrders.length} workflow(s) have been running for more than 30 minutes`,
      action: 'Check n8n execution logs. Consider manually marking as failed in Supabase.',
      recommendation: `UPDATE orders SET execution_status='failed', error_message='Workflow timeout' WHERE amazon_order_id IN (${alerts.map(a => `'${a.orderId}'`).join(', ')})`
    }
  }];

} catch (error) {
  console.error('❌ Error checking for stuck workflows:', error);
  return [];
}

// Log alert (you can replace this with Slack/Email node)
const alertData = $input.first().json;

if (!alertData.alert) {
  return [];
}

console.log('=== STUCK WORKFLOW ALERT ===');
console.log(`Level: ${alertData.level}`);
console.log(`Message: ${alertData.message}`);
console.log(`Count: ${alertData.count}`);
console.log('Workflows:');
alertData.workflows.forEach(w => {
  console.log(`  - ${w.orderId}: ${w.workflow} (${w.runningMinutes} min)`);
});
console.log(`Action: ${alertData.action}`);
console.log(`SQL: ${alertData.recommendation}`);

// TODO: Send to Slack/Email
// For now just logging

return [{ json: alertData }];

// Reset capacity counter when we have capacity
if ($execution.customData) {
  $execution.customData.capacityFullCycles = 0;
}

// Route order to correct workflow based on next_workflow field
const orders = $input.all();

if (!orders || orders.length === 0) {
  console.log('No orders to route');
  return [];
}

const routed = {
  workflow2A: [],
  workflow2B: [],
  workflow3: []
};

for (const item of orders) {
  const order = item.json;
  const nextWorkflow = order.next_workflow;

  console.log(`Order ${order.amazon_order_id}: Route to ${nextWorkflow}`);

  if (nextWorkflow === '2A') {
    routed.workflow2A.push(order);
  } else if (nextWorkflow === '2B') {
    routed.workflow2B.push(order);
  } else if (nextWorkflow === '3') {
    routed.workflow3.push(order);
  } else {
    console.warn(`⚠️ Unknown workflow: ${nextWorkflow} for order ${order.amazon_order_id}`);
  }
}

console.log(`Routing summary:`);
console.log(`  2A: ${routed.workflow2A.length} orders`);
console.log(`  2B: ${routed.workflow2B.length} orders`);
console.log(`  3: ${routed.workflow3.length} orders`);

return [{ json: routed }];

// Process 2A orders
const routing = $input.first().json;
const orders2A = routing.workflow2A || [];

if (orders2A.length === 0) {
  console.log('No orders for 2A');
  return [];
}

console.log(`=== PROCESSING ${orders2A.length} ORDERS FOR 2A ===`);

return orders2A.map(order => ({
  json: {
    orderId: order.amazon_order_id,
    characterHash: order.character_hash,
    characterSpecs: order.character_specs,
    bookSpecs: order.book_specs,
    orderDbId: order.id,
    workflow: '2A'
  }
}));

// Process 2B orders
const routing = $input.first().json;
const orders2B = routing.workflow2B || [];

if (orders2B.length === 0) {
  console.log('No orders for 2B');
  return [];
}

console.log(`=== PROCESSING ${orders2B.length} ORDERS FOR 2B ===`);

// Keep payload minimal; W2B will pull any needed URLs or keys itself
return orders2B.map(order => ({
  json: {
    orderId: order.amazon_order_id,
    characterHash: order.character_hash,
    orderDbId: order.id,
    workflow: '2B'
  }
}));

// Process Workflow 3 orders
const routing = $input.first().json;
const orders3 = routing.workflow3 || [];

if (orders3.length === 0) {
  console.log('No orders for Workflow 3');
  return [];
}

console.log(`=== PROCESSING ${orders3.length} ORDERS FOR WORKFLOW 3 ===`);

const prefix = 'book-mvp-simple-adventure/orders';

return orders3.map(order => ({
  json: {
    orderId: order.amazon_order_id,
    // Durable key (bucket is private). Router will exchange this for a signed GET URL.
    oneManifestKey: `${prefix}/${order.amazon_order_id}/manifests/1-manifest.json`,
    characterHash: order.character_hash,
    orderDbId: order.id,
    workflow: '3'
  }
}));

// Fetch a signed GET URL for oneManifestKey via backend
const item = $input.first().json;
const endpoint = process.env.R2_SIGNED_URL_ENDPOINT || 'https://admin.littleherolabs.com/api/r2/signed-url';
const token = process.env.BACKEND_API_TOKEN || '';
const ttl = Number(process.env.R2_SIGNED_URL_TTL || 600);

if (!item.oneManifestKey) {
  throw new Error('Missing oneManifestKey');
}

const res = await this.helpers.request({
  method: 'GET',
  uri: endpoint,
  qs: { key: item.oneManifestKey, bucket: 'little-hero-orders', expiresIn: ttl },
  headers: token ? { Authorization: `Bearer ${token}` } : {},
  json: true
});

const oneManifestUrl = res.url || res.data?.url || res.json?.url || res.result?.url;
if (!oneManifestUrl) {
  throw new Error('Signed URL endpoint did not return a URL');
}

return [{ json: { ...item, oneManifestUrl } }];
